return ['project-id-version'=>'Lingua Forge 2.1.0','report-msgid-bugs-to'=>'https://wordpress.org/support/plugin/lingua-forge','last-translator'=>'admin','language-team'=>'Russian','mime-version'=>'1.0','content-type'=>'text/plain; charset=UTF-8','content-transfer-encoding'=>'8bit','pot-creation-date'=>'2026-06-01T15:14:22+00:00','po-revision-date'=>'2026-06-03 15:33+0000','x-generator'=>'Loco https://localise.biz/','x-domain'=>'lingua-forge','language'=>'ru_RU','plural-forms'=>'nplurals=3; plural=(n%10==1 && n%100!=11 ? 0 : n%10 >= 2 && n%10<=4 &&(n%100<10||n%100 >= 20)? 1 : 2);','x-loco-version'=>'2.8.5; wp-7.0; php-8.3.31','messages'=>['"%1$s %2$s" saved.'=>'"%1$s %2$s" сохранено.','"%1$s" created. %2$d template updated.'=>'"%1$s" создан. %2$d шаблонов обновлено.' . "\0" . '"%1$s" создан. %2$d шаблонов обновлено.' . "\0" . '','"%s" created.'=>'"%s" создан.','%d language not yet linked'=>'%d языков ещё не связаны' . "\0" . '%d языков ещё не связаны' . "\0" . '','%d link updated.'=>'Обновлена %d ссылка.' . "\0" . 'Обновлено %d ссылок.' . "\0" . '','%d locale pack installed.'=>'Установлен %d пакет локализации.' . "\0" . 'Установлено %d пакетов локализации.' . "\0" . '','%d navigation reference updated.'=>'Обновлена %d навигационная ссылка.' . "\0" . 'Обновлено %d навигационных ссылок.' . "\0" . '','%d part reference updated.'=>'Обновлена %d ссылка на часть шаблона.' . "\0" . 'Обновлено %d ссылок на части шаблона.' . "\0" . '','%s Archive'=>'%s Архив','(avg %.1f hits/block)'=>'(в среднем %.1f обращений/блок)','(avg %.1f hits/entry)'=>'(среднее %.1f ударов/запись)','(disabled)'=>'(отключено)','({skipped} had no replaceable links — re-scan to investigate)'=>'({skipped} не имели заменяемых ссылок — повторите сканирование для проверки)','.txt file(s) in the directory'=>'.txt файл(ы) в каталоге','<strong>Lingua Forge:</strong> %1$d localized template(s) from the &#8220;%2$s&#8221; theme are preserved in the database but are currently inactive. They will become active again if you reactivate that theme. To carry your translations to the new theme, regenerate them via <strong>Settings → Lingua Forge → Router → FSE scaffold</strong>.'=>'<strong>Lingua Forge:</strong> %1$d локализованный(ые) шаблон(ы) из темы &#8220;%2$s&#8221; сохранены в базе данных, но в настоящее время неактивны. Они снова станут активными, если вы повторно активируете эту тему. Чтобы перенести ваши переводы на новую тему, regenerated их через <strong>Настройки → Lingua Forge → Маршрутизатор → FSE scaffold</strong>.','<strong>{n}</strong> auto-fixable link(s)'=>'<strong>{n}</strong> автоматически исправляемых ссылки','<strong>{n}</strong> link(s) needing manual review'=>'<strong>{n}</strong> ссылок требуют ручной проверки','<strong>{n}</strong> stale path(s)'=>'<strong>{n}</strong> устаревший(ие) путь(и)','<strong>{n}</strong> template issue(s)'=>'<strong>{n}</strong> проблема(ы) шаблона','Accepts compiled .mo files only. Filename must follow the pattern {textdomain}-{locale}.mo. Uploading a file with the same name as an existing one will replace it.'=>'Принимаются только скомпилированные файлы .mo. Имя файла должно соответствовать шаблону {textdomain}-{locale}.mo. Загрузка файла с таким же именем, как существующий, заменит его.','Action'=>'Действие','Actions'=>'Действия','active'=>'активен','Active Languages'=>'Активные языки','Active languages: add each language you want to support. Each language gets a URL prefix or subdomain and an hreflang tag in the page &lt;head&gt;.'=>'Активные языки: добавьте каждый язык, который вы хотите поддерживать. Каждый язык получает префикс URL или поддомен и тег hreflang в разделе &lt;head&gt; страницы.','Active Provider'=>'Активный поставщик','Add entry'=>'Добавить запись','Add instructions to improve the draft — e.g. make it shorter, add a conclusion section, use a more formal register, include an FAQ block…'=>'Добавьте инструкции для улучшения черновика — например, сделайте его короче, добавьте раздел с выводами, используйте более официальный стиль, включите блок FAQ…','Add instructions to improve the draft — e.g. make it shorter, add a conclusion section, use a more formal register…'=>'Добавьте инструкции для улучшения черновика — например, сделайте его короче, добавьте раздел с выводом, используйте более формальный стиль…','Add new entry'=>'Добавить новую запись','Add one term per row. Both the source term and the target rendering are required. The language pair determines which translation jobs the constraint applies to.'=>'Добавьте один термин на строку. Требуются как исходный термин, так и целевое отображение. Пара языков определяет, к каким заданиям перевода применяется ограничение.','Adds a link to the home page so visitors can browse in their language.'=>'Добавляет ссылку на главную страницу, чтобы посетители могли просматривать сайт на своем языке.','Administrators only (manage_options)'=>'Только администраторы (manage_options)','After changing the primary language, flush permalinks (section below) for the URL routing to update.'=>'После изменения основного языка обновите постоянные ссылки (раздел ниже), чтобы обновить маршрутизацию URL.','After changing URL structure settings (path prefix ↔ subdomain), always visit Settings → Permalinks and click Save Changes to flush the rewrite rules.'=>'После изменения настроек структуры URL (префикс пути ↔ поддомен) всегда посещайте Настройки → Постоянные ссылки и нажимайте Сохранить изменения, чтобы сбросить правила переписывания.','AI Behaviour Preset'=>'Настройка поведения ИИ','AI cache cleared. %d entry was removed.'=>'Кэш ИИ очищен. Удалено записей: %d.' . "\0" . 'Кэш ИИ очищен. Удалено записей: %d.' . "\0" . '','AI Cache: lists cached AI responses with hit counts. Clear the whole cache or a single post\'s entries. Use "Clear" before testing a translation change — cached results are returned even when you change the AI preset or model until the cache entry is evicted.'=>'Кэш AI: список кешированных ответов AI с подсчетом попаданий. Очистите весь кэш или записи отдельного поста. Используйте "Очистить" перед тестированием изменения перевода — кешированные результаты возвращаются даже при изменении пресета или модели AI, пока запись в кэше не будет удалена.','AI features are optional. Language routing, hreflang, the language switcher, and the translation group system all work without a provider configured.'=>'Функции AI являются необязательными. Маршрутизация по языкам, hreflang, переключатель языков и система групп переводов работают без настроенного провайдера.','AI Limits & Security'=>'Ограничения и безопасность ИИ','AI provider returned an empty response.'=>'Поставщик ИИ вернул пустой ответ.','AI Usage'=>'Использование ИИ','Aim for 120–160 characters. Leave empty to use the excerpt fallback.'=>'Цель — 120–160 символов. Оставьте пустым, чтобы использовать резервное копирование из аннотации.','All time'=>'Все время','Allow editors to lock individual blocks'=>'Разрешить редакторам блокировать отдельные блоки','Allow Gutenberg template-editing mode on post screens'=>'Разрешить режим редактирования шаблонов Gutenberg на страницах постов','Also delete language assignments, translation relationships, meta descriptions, glossary, and Translation Memory when the plugin is uninstalled'=>'Также удалять назначения языков, отношения перевода, метаописания, глоссарий и кеш памяти перевода при удалении плагина.','Also generate meta description'=>'Также создать мета-описание','Alternative (server-side):'=>'Альтернатива (серверная сторона):','An unknown error occurred.'=>'Произошла неизвестная ошибка.','and'=>'и','Anthropic (Claude)'=>'Anthropic (Клод)','any'=>'любой','API calls saved by cache'=>'API вызовы, сохраненные в кэше','API Key'=>'Ключ API','API Keys'=>'API-ключи','API Keys Tab'=>'Вкладка API ключей','API Response Cache'=>'Кэш ответов API','Applied ✓'=>'Применено ✓','Apply failed — please try again.'=>'Не удалось применить — попробуйте еще раз.','Apply to Block'=>'Применить к блоку','Apply to Editor'=>'Применить к редактору','Apply to Footnote'=>'Применить к сноске','Apply to Meta Description'=>'Применить к мета-описанию','Apply translation'=>'Применить перевод','Applying…'=>'Применение…','Approximate size'=>'Приблизительный размер','Archive'=>'Архив','Archive: %s'=>'Архив: %s','Authors and above (edit_published_posts)'=>'Авторы и выше (edit_published_posts)','Behavior'=>'Поведение','Behavior: choose the AI preset (Literal, Balanced, Creative), add site-wide custom prompt instructions, enable or disable automatic post-save translation, and configure the Translation Memory.'=>'Поведение: выберите пресет AI (Literal, Balanced, Creative), добавьте глобальные инструкции для сайта, включите или отключите автоматический перевод при сохранении поста и настройте Память переводов.','Block Content'=>'Блок содержимого','block descriptionRenders a polite notice when the current page is being shown in its source language because no translation exists for the visitor\'s language. Driven by the Lingua Forge router\'s LINGUAFORGE_LANG_FALLBACK_ACTIVE signal — emits nothing when a translation exists for the request locale.'=>'Отображает вежливое уведомление, когда текущая страница показывается на исходном языке, потому что для языка посетителя перевод отсутствует. Управляется сигналом LINGUAFORGE_LANG_FALLBACK_ACTIVE маршрутизатора Lingua Forge — ничего не выводит, когда для запрошенного языка есть перевод.','Block Editor'=>'Редактор блоков','block keywordfallback'=>'запасной вариант','block keywordi18n'=>'i18n','block keywordlanguage'=>'язык','block keywordlinguaforge'=>'linguaforge','block keywordtranslation'=>'перевод','Block locking'=>'Блокировка','Block patterns registered for custom post types. Use the Translate button to produce a language variant. The translated content is saved here and can be copied into any CPT post from the block editor Pattern inserter or used as a starting point for a Synced Pattern (Reusable Block).'=>'Шаблоны блоков, зарегистрированные для пользовательских типов записей. Используйте кнопку Перевести для создания варианта на другом языке. Переведённый контент сохраняется здесь и может быть скопирован в любой пост CPT через вставщик шаблонов редактора блоков или использован как отправная точка для синхронизированного шаблона (многоразовый блок).','block titleMissing Translation Notice'=>'Уведомление о пропущенном переводе','Block translation reuses'=>'Повторное использование блоков перевода','Block-level translation cache shared across posts. When enabled, identical blocks (same markup, language pair, and glossary) are served from memory instead of calling the AI again. Configure in Settings → Behavior.'=>'Кэш перевода блоков на уровне блока, общий для постов. При включении одинаковые блоки (одинаковый разметка, пара языков и глоссарий) обслуживаются из памяти вместо повторного вызова AI. Настройка в Настройки → Поведение.','Browser language redirect'=>'Перенаправление по языку браузера','Built-in preset instructions:'=>'Встроенные предустановленные инструкции:','Bulletize (•-prefixed)'=>'Создать список (с маркерами •-)','Cache translated equivalents at the block level so reusable content (shared footers, sidebars, accordions, boilerplate-heavy legal sections) does not pay an API call every time. When enabled, the translation flow parses each post into blocks, looks each block up in the cache, and sends only uncached blocks to the AI in a single batched request. Glossary edits and Compliance preset changes automatically invalidate affected cached translations. View statistics and clear the cache under Maintenance.'=>'Кэширование переводных эквивалентов на уровне блоков, чтобы повторно используемый контент (общие футеры, боковые панели, аккордеоны, разделы с юридической информацией) не вызывал API-запрос при каждом использовании. При включении поток перевода разбирает каждый пост на блоки, ищет каждый блок в кэше и отправляет только неперекэшированные блоки в один пакетный запрос к ИИ. Редактирование глоссария и изменения предустановки соответствия автоматически аннулируют связанные кэшированные переводы. Просматривайте статистику и очищайте кэш в разделе Обслуживание.','cached'=>'кэшировано','Cached API responses'=>'Кэшированные ответы API','Cached block translations'=>'Кэшированные переводы блоков','Cancel'=>'Отмена','Cannot determine target language from slug.'=>'Невозможно определить целевой язык по слагу.','Cap how much AI usage the site can generate and restrict which user roles may trigger paid AI calls. Sits on top of the per-user rate limit (30 requests / minute, hardcoded) that already protects against single-user runaway loops.'=>'Ограничьте использование ИИ на сайте и ограничьте роли пользователей, которые могут запускать платные вызовы ИИ. Расположено поверх ограничения по количеству запросов на пользователя (30 запросов / минута, жестко задано), которое уже защищает от бесконтрольных циклов одного пользователя.','chars'=>'символов','Chunk translated'=>'Фрагмент переведен','Chunk translated to:'=>'Фрагмент переведен в:','Clear'=>'Очистить','Clear All'=>'Очистить всё','Clear all cached AI results? Future requests will trigger fresh API calls until the cache rebuilds.'=>'Очистить все кэшированные результаты ИИ? В будущем запросы вызовут новые API-запросы, пока кэш не будет перестроен.','Clear API Response Cache'=>'Очистить кэш ответов API','Clear Debug Files'=>'Очистить файлы отладки','Clear hints'=>'Очистить подсказки','Clear input'=>'Очистить ввод','Clear the entire Translation Memory? Future translations will rebuild the cache as they run.'=>'Очистить весь кеш памяти перевода? Будущие переводы будут заново строить кеш по мере выполнения.','Clear Translation Memory'=>'Очистить кеш памяти перевода','Close'=>'Закрыть','Close language panel'=>'Закрыть панель языков','Close popover'=>'Закрыть всплывающее окно','Compliance Preset'=>'Предустановка соответствия','Content generated'=>'Контент сгенерирован','Content Generator'=>'Генератор контента','Content ready'=>'Контент готов','Contributors and above — default (edit_posts)'=>'Соавторы и выше — по умолчанию (edit_posts)','Control how much content is sent to the AI and how large the response can be. Leave a field blank to use the built-in default (shown as placeholder). Raise these values if large pages are being cut off; lower them to reduce API costs.'=>'Контролируйте, сколько контента отправляется в ИИ и насколько большим может быть ответ. Оставьте поле пустым, чтобы использовать встроенное значение по умолчанию (показано как заполнитель). Увеличьте эти значения, если большие страницы обрезаются; уменьшите — чтобы снизить затраты на API.','Controls the token budget and input limits for the AI Content Generator feature. Leave fields blank to use the built-in defaults.'=>'Управляет бюджетом токенов и лимитами ввода для функции генерации контента ИИ. Оставьте поля пустыми, чтобы использовать встроенные значения по умолчанию.','Controls what happens when an administrator deletes the plugin from Plugins → Installed Plugins → Delete. Plugin settings and AI caches are always removed. Language assignments and translation relationships are kept by default so an accidental uninstall or a reinstall can pick up where it left off.'=>'Управляет тем, что происходит, когда администратор удаляет плагин из Plugins → Installed Plugins → Delete. Настройки плагина и кеши AI всегда удаляются. Назначения языков и отношения перевода по умолчанию сохраняются, чтобы случайное удаление или повторная установка могли продолжить работу с того места, где остановились.','Conversational'=>'Разговорный','Copied ✓'=>'Скопировано ✓','Copy'=>'Копировать','Copy markup'=>'Копировать разметку','Copy the result and paste it wherever needed (e.g. directly into the footnote field).'=>'Скопируйте результат и вставьте туда, где нужно (например, прямо в поле сноски).','Copy to safe storage'=>'Копировать в безопасное хранилище','Could not add entry: source term and target term are required.'=>'Не удалось добавить запись: требуются исходный термин и целевой термин.','Could not copy the file. Check that the uploads folder is writable.'=>'Не удалось скопировать файл. Проверьте, что папка uploads доступна для записи.','Could not instantiate the provider.'=>'Не удалось создать экземпляр поставщика.','Could not save the file. Check that the uploads folder is writable.'=>'Не удалось сохранить файл. Проверьте, что папка uploads доступна для записи.','Could not save the glossary entry.'=>'Не удалось сохранить запись в глоссарии.','CPT Block Patterns'=>'Шаблоны блоков CPT','Create'=>'Создать','Create missing'=>'Создать отсутствующее','Creating translations for post type "%s" requires an active integration. Please ensure the required integration is installed and active.'=>'Создание переводов для типа поста "%s" требует активной интеграции. Пожалуйста, убедитесь, что необходимая интеграция установлена и активирована.','Creating…'=>'Создание…','Creative / Marketing'=>'Креативный / Маркетинг','Creative / Marketing instructions'=>'Креативные / маркетинговые инструкции','Current content (will be overwritten)'=>'Текущее содержание (будет перезаписано)','Current title'=>'Текущий заголовок','Current: {current}'=>'Текущий: {current}','Currently inherited from the %s constant. Selecting a value here will override it.'=>'В настоящее время наследуется от константы %s. Выбор значения здесь переопределит её.','Currently skipped for posts that use block-comment attribute placeholders (wp:details summary fields, etc.) — they fall through to the existing single-call translation path.'=>'В настоящее время пропускается для постов, использующих заполнители атрибутов блок-комментариев (wp:details, поля сводки и т. д.) — они переходят к существующему однократному пути перевода.','Currently:'=>'В настоящее время:','Custom'=>'Пользовательский','Daily AI quota reached (%1$d requests). Resets at %2$s UTC.'=>'Дневной лимит запросов к ИИ достигнут (%1$d запросов). Обновление в %2$s UTC.','Daily request limit'=>'Ежедневный лимит запросов','Debug Files'=>'Файлы отладки','Debug files cleared. %d file was removed.'=>'Файлы отладки очищены. Удален %d файл.' . "\0" . 'Файлы отладки очищены. Удалено %d файлов.' . "\0" . '','Debug logging'=>'Ведение журнала отладки','Debug logging disabled.'=>'Ведение журнала отладки отключено.','Debug logging enabled.'=>'Ведение журнала отладки включено.','Debug: enable the debug log to capture AI prompts and API responses to a local file. Disable after troubleshooting — debug mode writes a file on every AI request.'=>'Отладка: включите журнал отладки для захвата подсказок AI и ответов API в локальный файл. Отключите после устранения проблем — режим отладки записывает файл при каждом запросе AI.','Delete'=>'Удалить','Delete all .txt files in the debug directory? The directory itself will remain so future debug writes still land cleanly.'=>'Удалить все .txt файлы в каталоге отладки? Сам каталог останется, чтобы будущие записи отладки могли сохраняться без проблем.','Delete all files for this override (both .mo and .po)?'=>'Удалить все файлы для этого переопределения (оба .mo и .po)?','Delete content data on uninstall'=>'Удалить данные контента при удалении','Delete this glossary entry?'=>'Удалить эту запись из глоссария?','Describe what to write — topic, key points, structure…'=>'Опишите, что писать — тема, ключевые моменты, структура…','Directory'=>'Каталог','Disable during prompt tuning or when you need every request to reach the AI provider. Disabling does not delete cached entries — re-enabling restores them. Increasing API spend immediately on busy sites is expected when disabled.'=>'Отключите при настройке подсказок или когда требуется, чтобы каждый запрос достигал провайдера AI. Отключение не удаляет кешированные записи — повторное включение восстанавливает их. Немедленное увеличение расходов API на загруженных сайтах ожидается при отключении.','Display'=>'Отображение','Displays the Lingua Forge language switcher.'=>'Отображает переключатель языков Lingua Forge.','Documentation'=>'Документация','Done'=>'Готово','Done — {done} of {total} post(s) fixed.'=>'Готово — исправлено {done} из {total} постов.','Down'=>'Вниз','Download and install a WordPress core language pack directly from WordPress.org. Once installed, the locale becomes available for URL routing and the AI translation workflow. The list of available languages is fetched on demand — click the button below to load it.'=>'Загрузите и установите пакет языка ядра WordPress напрямую с WordPress.org. После установки локаль станет доступной для маршрутизации URL и рабочего процесса перевода AI. Список доступных языков загружается по требованию — нажмите кнопку ниже, чтобы загрузить его.','Dropdown direction'=>'Направление выпадающего меню','Editors and above (edit_others_posts)'=>'Редакторы и выше (edit_others_posts)','Enable API response caching'=>'Включить кеширование ответов API','Enable block-level translation cache reuse across posts'=>'Включить повторное использование кэша перевода на уровне блоков между постами','Enter your API key for at least one AI provider. Keys are encrypted at rest using AES-256-GCM with a site-specific secret (LINGUAFORGE_SECRET). Do not share database exports without rotating the secret first.'=>'Введите ваш API ключ для хотя бы одного провайдера AI. Ключи шифруются при хранении с помощью AES-256-GCM с секретом, уникальным для сайта (LINGUAFORGE_SECRET). Не делитесь экспортами базы данных без предварительной ротации секрета.','environment variable'=>'переменная окружения','Error'=>'Ошибка','Expand'=>'Расширить','Expected: {expected}'=>'Ожидаемый: {expected}','Extra guidance — tone, style, constraints, target audience…'=>'Дополнительные рекомендации — тон, стиль, ограничения, целевая аудитория…','Extra guidance — tone, style, constraints…'=>'Дополнительные рекомендации — тон, стиль, ограничения…','Failed. Please try again.'=>'Не удалось. Пожалуйста, попробуйте снова.','Feature'=>'Функция','Features are grouped into two tiers. Enter the exact model identifier for each tier and provider. Leave a field blank to use the built-in default (shown as placeholder). Only the active provider\'s models are called at runtime — configure the others in advance if you plan to switch.'=>'Функции сгруппированы в два уровня. Введите точный идентификатор модели для каждого уровня и поставщика. Оставьте поле пустым, чтобы использовать встроенное значение по умолчанию (отображается как заполнитель). Только модели активного поставщика вызываются во время выполнения — настройте остальные заранее, если планируете переключение.','File copied to safe storage successfully.'=>'Файл успешно скопирован в безопасное хранилище.','Files'=>'Файлы','Files land in the directory below. Useful for diagnosing translation issues — turn off once you have what you need so the files do not accumulate. You can also force this from wp-config.php with `define( \'LINGUAFORGE_AI_DEBUG\', true );` which overrides the toggle.'=>'Файлы сохраняются в указанной ниже директории. Полезно для диагностики проблем с переводом — отключите после получения нужных данных, чтобы файлы не накапливались. Также можно принудительно установить это через wp-config.php с помощью `define( \'LINGUAFORGE_AI_DEBUG\', true );`, что переопределяет переключатель.','Filter'=>'Фильтр','Filter with linguaforge_debug_dir to redirect debug output to a non-public location.'=>'Используйте фильтр с linguaforge_debug_dir для перенаправления вывода отладки в недоступное для публики место.','Fix'=>'Исправить','Fix All'=>'Исправить всё','Fix all links'=>'Исправить все ссылки','Fix all parts'=>'Исправить все части','Fix Links'=>'Исправить ссылки','Fix Nav'=>'Исправить навигацию','Fix Parts'=>'Исправить части','Fix Template'=>'Исправить шаблон','Fixing {n} / {total}…'=>'Исправление {n} / {total}…','Fixing…'=>'Исправление…','Flush Permalink Rules'=>'Обновить правила постоянных ссылок','Flush Permalinks'=>'Обновить постоянные ссылки','Footnote Content'=>'Содержание сноски','footnote(s) translated — applied together with content.'=>'переведены сноски — применены вместе с содержимым.','Footnotes'=>'Сноски','Footnotes payload (advanced)'=>'Дополнительные сноски (расширенные)','Forbidden'=>'Запрещено','Forced OFF by the LINGUAFORGE_AI_DEBUG constant in wp-config.php. Remove that line to control this toggle from here.'=>'Принудительно ВЫКЛЮЧЕНО с помощью константы LINGUAFORGE_AI_DEBUG в wp-config.php. Удалите эту строку, чтобы управлять этим переключателем отсюда.','Forced ON by the LINGUAFORGE_AI_DEBUG constant in wp-config.php. Remove that line to control this toggle from here.'=>'Принудительно ВКЛЮЧЕНО с помощью константы LINGUAFORGE_AI_DEBUG в wp-config.php. Удалите эту строку, чтобы управлять этим переключателем отсюда.','Found {parts} across <strong>{total}</strong> of <strong>{scanned}</strong> scanned post(s) for <strong>{lang}</strong>.'=>'Обнаружено {parts} в <strong>{total}</strong> из <strong>{scanned}</strong> просканированных постов для <strong>{lang}</strong>.','From'=>'От','Front Page'=>'Главная страница','FSE localisation: scaffold, translate, and fix links in Full Site Editing templates and template parts directly from this tab.'=>'Локализация FSE: создавайте каркасы, переводите и исправляйте ссылки в шаблонах и частях шаблонов полного редактирования сайта прямо из этой вкладки.','FSE templates seeded from the active theme. Create then customise in the Site Editor.'=>'Шаблоны FSE, созданные из активной темы. Создавайте и настраивайте в редакторе сайта.','Full Article'=>'Полная статья','Full post'=>'Полный пост','General'=>'Общее','Generate'=>'Создать','Generate Content'=>'Генерировать контент','Generate content…'=>'Генерация контента…','Generate Excerpt'=>'Создать выдержку','Generate Meta Description'=>'Создать мета-описание','Generated Content'=>'Сгенерированный контент','Generated meta description'=>'Сгенерированное мета-описание','Generating…'=>'Генерация…','Generation failed.'=>'Не удалось сгенерировать.','Getting started'=>'Начало работы','Global AI preset'=>'Глобальная предустановка ИИ','Global default (%s)'=>'Глобальные настройки по умолчанию (%s)','Glossary'=>'Глоссарий','Glossary entry added.'=>'Запись в глоссарии добавлена.','Glossary entry removed.'=>'Запись в глоссарии удалена.','Glossary Tab'=>'Вкладка Глоссарий','Google (Gemini)'=>'Google (Gemini)','Hide'=>'Скрыть','Hints'=>'Подсказки','Home link text'=>'Текст ссылки на главную','How it should appear in the translation. Type the same value as the source term to instruct the AI to preserve it verbatim.'=>'Как она должна выглядеть в переводе. Введите то же значение, что и исходный термин, чтобы указать ИИ сохранить его дословно.','https://github.com/leotiger/lingua-forge'=>'https://github.com/leotiger/lingua-forge','https://lingua-forge.com'=>'https://lingua-forge.com','Icon + label'=>'Иконка + метка','Icon only'=>'Только иконка','If checked, uninstalling the plugin will permanently delete all language assignments, translation relationships, meta descriptions, per-page presets, the AI glossary, and Translation Memory for every post on this site. This cannot be undone. Leave unchecked unless you are fully removing multilingual support from the site.'=>'Если установлено, удаление плагина навсегда удалит все назначения языков, отношения перевода, метаописания, пресеты для страниц, глоссарий AI и кеш памяти перевода для каждого поста на этом сайте. Это действие нельзя отменить. Не ставьте галочку, если вы полностью удаляете мультиязычную поддержку сайта.','Improve writing'=>'Улучшить написание','Informative'=>'Информативный','Input tokens'=>'Входные токены','Install'=>'Установить','Install a Language'=>'Установить язык','Installing…'=>'Установка…','Instructions (optional)'=>'Инструкции (опционально)','Instructions / key points'=>'Инструкции / ключевые моменты','Integration API'=>'Интеграционный API','Internal Link Fixer'=>'Исправитель внутренних ссылок','Introduction only'=>'Только введение','Invalid file reference.'=>'Недопустимая ссылка на файл.','Invalid filename.'=>'Недопустимое имя файла.','Invalid language.'=>'Недопустимый язык.','Invalid locale code.'=>'Недопустимый код локали.','Invalid or primary language.'=>'Недопустимый или основной язык.','Invalid post type.'=>'Недопустимый тип поста.','Invalid template part.'=>'Недопустимая часть шаблона.','Invalid template type.'=>'Недопустимый тип шаблона.','Key points, ideas, or structure to build from…'=>'Ключевые моменты, идеи или структура, на которых нужно строить…','Keys are encrypted with AES-256-CBC before being stored in the WordPress database. The encryption secret is derived from your WordPress auth salts (wp-config.php), so plaintext keys never touch the database.'=>'Ключи API шифруются с помощью AES-256-CBC перед сохранением в базе данных WordPress. Секрет шифрования берется из ваших солей авторизации WordPress (wp-config.php), поэтому открытые ключи никогда не попадают в базу данных.','Language'=>'Язык','Language %s installed successfully.'=>'Язык %s успешно установлен.','Language (optional)'=>'Язык (опционально)','Language installation is disabled on this server (DISALLOW_FILE_MODS is set).'=>'Установка языков отключена на этом сервере (установлена константа DISALLOW_FILE_MODS).','Language installation is disabled on this server. The DISALLOW_FILE_MODS constant is set in wp-config.php. Install language packs manually via WP-CLI: wp language core install de_DE'=>'Установка языков отключена на этом сервере. В файле wp-config.php установлена константа DISALLOW_FILE_MODS. Установите языковые пакеты вручную через WP-CLI: wp language core install de_DE','Language label'=>'Метка языка','Language Overrides'=>'Переопределение языка','Language Overrides: manage custom .po/.mo override files for the Lingua Forge UI strings. Use this instead of editing plugin files directly — overrides survive updates.'=>'Переопределения языка: управляйте пользовательскими файлами .po/.mo для строк интерфейса Lingua Forge. Используйте это вместо редактирования файлов плагина — переопределения сохраняются при обновлениях.','Language pack installation failed. The language may already be installed, the locale code may be incorrect, or your server may block file writes.'=>'Не удалось установить языковой пакет. Язык может уже быть установлен, код локали может быть неправильным, или ваш сервер блокирует запись файлов.','Language Setup'=>'Настройка языка','Language Switcher'=>'Переключатель языков','Language switcher'=>'Переключатель языков','Language-specific copies of the theme\'s template parts. Once scaffolded, templates are updated to reference the language-specific part.'=>'Копии шаблонов темы, специфичные для языка. После создания шаблонов они обновляются для ссылки на языковую часть.','Language:'=>'Язык:','Languages currently known to the router (derived from installed WordPress locale packs plus the primary language). Install additional language packs in the section below to make more languages available for routing and translation.'=>'Языки, в настоящее время известные маршрутизатору (полученные из установленных пакетов локализации WordPress и основного языка). Установите дополнительные языковые пакеты в разделе ниже, чтобы сделать больше языков доступными для маршрутизации и перевода.','Last 30 days'=>'Последние 30 дней','Last 7 days'=>'Последние 7 дней','Lead paragraph (≤60 w)'=>'Вводный параграф (≤60 слов)','Leave a model field blank to use the built-in default for that tier. The placeholder text shows which model will be used.'=>'Оставьте поле модели пустым, чтобы использовать встроенное значение по умолчанию для этого уровня. Текст-заполнитель показывает, какая модель будет использоваться.','Leave blank for brand names and language-agnostic terms that should be enforced regardless of which language we are translating from.'=>'Оставьте пустым для названий брендов и терминов, не зависящих от языка, которые должны сохраняться независимо от языка перевода.','Leave blank to apply this entry to all target languages — ideal for brand names, abbreviations, and terms that must be preserved verbatim in every translation.'=>'Оставьте пустым, чтобы применить эту запись ко всем целевым языкам — идеально для названий брендов, аббревиатур и терминов, которые должны сохраняться дословно в каждом переводе.','Leave blank to keep the existing key. Enter a new value to replace it.'=>'Оставьте пустым, чтобы сохранить существующий ключ. Введите новое значение для его замены.','Leave blank to use the built-in default. Clearing a saved override restores the default on next save.'=>'Оставьте пустым, чтобы использовать встроенное значение по умолчанию. Очистка сохранённого переопределения восстанавливает значение по умолчанию при следующем сохранении.','Legal / Compliance'=>'Юридический / Соответствие','Legal / Compliance instructions'=>'Юридические / нормативные инструкции','Light'=>'Лёгкий','Light (default — fast and cost-effective)'=>'Легкий (по умолчанию — быстрый и экономичный)','Light (fast and cost-effective — Haiku / Flash)'=>'Легкий (быстрый и экономичный — Haiku / Flash)','Light: used for meta descriptions and excerpt generation — fast, low cost.'=>'Легкий: используется для метаописаний и генерации выдержек — быстро, недорого.','Limit results to pages in the given Lingua Forge language code.'=>'Ограничить результаты страницами с указанным кодом языка Lingua Forge.','Limits'=>'Лимиты','Lingua Forge'=>'Лингва Фордж','Lingua Forge adds multilingual routing, AI-powered translation, hreflang SEO tags, and a language switcher to your WordPress site.'=>'Lingua Forge добавляет многоязычную маршрутизацию, перевод с помощью AI, SEO теги hreflang и переключатель языков на ваш сайт WordPress.','Lingua Forge AI Tools'=>'Инструменты Lingua Forge AI','Lingua Forge restricts two Gutenberg features by default to keep editorial behavior consistent across languages. Opt in here when you need full Gutenberg / FSE capabilities.'=>'Lingua Forge по умолчанию ограничивает две функции Gutenberg, чтобы сохранить согласованное редакционное поведение во всех языках. Включите здесь, если вам нужны полные возможности Gutenberg / FSE.','Lingua Forge Settings'=>'Настройки Lingua Forge','Lingua Forge uses two independent caching layers to avoid redundant AI API calls. Use the tabs below to inspect and manage each one.'=>'Lingua Forge использует два независимых уровня кеширования, чтобы избежать избыточных вызовов API AI. Используйте вкладки ниже для проверки и управления каждым из них.','Lingua Forge uses two model tiers per provider:'=>'Lingua Forge использует два уровня моделей для каждого провайдера:','Lingua Forge — Quick Translate'=>'Лингва Фордж — Быстрый перевод','Lingua Forge — Settings'=>'Lingua Forge — Настройки','link(s)'=>'ссылка(и)','Links'=>'Ссылки','Load available languages'=>'Загрузить доступные языки','Loading…'=>'Загрузка…','Loco Translate stores its custom translations in wp-content/languages/loco/ — a location that can be silently wiped by a WP core update, plugin reinstall, or if Loco Translate itself is removed. Copying files here moves them into the Lingua Forge i18n-overrides directory, which persists through all of those events and is loaded automatically on every request.'=>'Loco Translate сохраняет свои пользовательские переводы в wp-content/languages/loco/ — расположение, которое может быть тихо удалено обновлением ядра WP, переустановкой плагина или удалением самого Loco Translate. Копирование файлов сюда перемещает их в каталог Lingua Forge i18n-overrides, который сохраняется при всех этих событиях и загружается автоматически при каждом запросе.','Loco Translate — Copy to Safe Storage'=>'Loco Translate — копировать в безопасное хранилище','Lowest WordPress capability allowed to trigger AI features. Tightening this on multi-author sites prevents Contributors or trial accounts from running paid AI calls. Override per-feature via the linguaforge_required_capability filter.'=>'Наименьшая возможность WordPress, позволяющая запускать функции ИИ. Ужесточение этого ограничения на сайтах с несколькими авторами предотвращает запуск платных вызовов ИИ со стороны соавторов или пробных аккаунтов. Переопределяется для каждой функции через фильтр linguaforge_required_capability.','Maintenance'=>'Обслуживание','Maintenance Tab'=>'Вкладка Обслуживание','Make casual'=>'Сделать неформальным','Make concise'=>'Сделать кратким','Make formal'=>'Сделать формальным','Mark citations needed'=>'Отметить необходимость цитат','Max context characters'=>'Максимальный контекст','Max hints characters'=>'Максимальное количество символов подсказок','Max input characters'=>'Максимальное количество символов входных данных','Max output tokens'=>'Максимальное количество токенов вывода','Maximum characters accepted from the input field. Default: 8 000.'=>'Максимальное количество символов, принимаемых из поля ввода. По умолчанию: 8000.','Maximum characters of existing post content passed to the AI as seed context when no Hints are provided. Default: 6 000.'=>'Максимальное количество символов существующего содержимого поста, передаваемого ИИ в качестве исходного контекста, если подсказки не предоставлены. По умолчанию: 6000.','Maximum characters read from the Hints field. Default: 2 000.'=>'Максимальное количество символов, читаемых из поля подсказок. По умолчанию: 2000.','Maximum number of characters of post content forwarded to the AI. 0 means no limit — the full content is always sent (recommended). Set a non-zero value only if your provider has a tight context window. A warning is written to the PHP error log whenever the content is trimmed.'=>'Максимальное количество символов содержимого поста, передаваемого ИИ. 0 означает отсутствие ограничения — полное содержимое всегда отправляется (рекомендуется). Установите ненулевое значение только если у вашего провайдера есть ограничение по контексту. В журнал ошибок PHP записывается предупреждение, когда содержимое обрезается.','Maximum number of tokens the AI may produce in a single translation response. If a translation is silently cut off at the end, increase this value. Default: 16 000.'=>'Максимальное число токенов, которое ИИ может сгенерировать за один ответ. Если перевод обрывается в конце, увеличьте это значение. По умолчанию: 16 000.','Maximum tokens the AI may produce per generation run. Raise this if full articles are being cut off. Default: 8 192.'=>'Максимальное количество токенов, которое ИИ может сгенерировать за один запуск. Увеличьте, если статьи обрезаются полностью. По умолчанию: 8192.','Maximum tokens the AI may produce per quick translation. Default: 2 000.'=>'Максимальное количество токенов, которое ИИ может сгенерировать за один быстрый перевод. По умолчанию: 2000.','Meta Description'=>'Мета-описание','Meta Description, Excerpt Generator'=>'Генератор мета-описаний, выдержек','Minimum role'=>'Минимальная роль','Missing pattern name or language.'=>'Отсутствует имя шаблона или язык.','Mode'=>'Режим','Model'=>'Модель','Model tier'=>'Уровень модели','Models'=>'Модели','Models Tab (General)'=>'Общие модели','Most recent cached block'=>'Последний кешированный блок','Most recent cached response'=>'Последний кешированный ответ','Multilingual routing, SEO meta tags, and AI content tools for WordPress. Combines language detection, URL routing, hreflang, meta descriptions, and AI-powered excerpt, meta, and translation features.'=>'Многоязычная маршрутизация, SEO метатеги и инструменты ИИ для контента для WordPress. Объединяет обнаружение языка, маршрутизацию URL, hreflang, метаописания и функции AI для кратких описаний, мета и переводов.','Name displayed in this language. Leave empty to use the source name.'=>'Имя, отображаемое на этом языке. Оставьте пустым, чтобы использовать исходное имя.','Navigation'=>'Навигация','Navigation has no content to translate.'=>'В навигации нет содержимого для перевода.','Navigation not found.'=>'Навигация не найдена.','Navigation posts are translated via the Router tab, not this button.'=>'Посты навигации переводятся через вкладку Router, а не этой кнопкой.','Navigation translation requires an active AI provider. Configure an API key in the API Keys tab.'=>'Перевод навигации требует активного поставщика AI. Настройте API-ключ во вкладке API-ключи.','Navigations'=>'Навигации','Network error — could not reach the WordPress AJAX endpoint.'=>'Ошибка сети — не удалось достичь конечной точки WordPress AJAX.','No %s version found in this translation group.'=>'В этой группе переводов не найдено версии %s.','No AI provider configured.'=>'Не настроен поставщик ИИ.','No AI usage recorded in the selected window (%s). Pick a wider range above.'=>'Использование ИИ не зафиксировано за выбранный период (%s). Выберите более широкий диапазон выше.','No AI usage recorded yet. Once an editor runs a translation, generates a meta description, or uses any other AI feature, totals will appear here.'=>'Пока что не зафиксировано использование ИИ. Как только редактор выполнит перевод, сгенерирует мета-описание или использует любую другую функцию ИИ, итоги появятся здесь.','No API key configured for this provider.'=>'Для этого поставщика не настроен API-ключ.','No built-in instructions — each AI feature uses its own tuned defaults. Fill in the Custom prompt instructions field below to add your own site-wide rules.'=>'Нет встроенных инструкций — каждая функция ИИ использует свои собственные настроенные параметры. Заполните поле пользовательских инструкций ниже, чтобы добавить свои правила для всего сайта.','No custom Loco Translate files found yet. They appear here once you save a translation in Loco Translate.'=>'Пока что пользовательские файлы Loco Translate не найдены. Они появятся здесь после сохранения перевода в Loco Translate.','No file was selected.'=>'Файл не выбран.','No glossary entries match the current filter. Clear the filter to see all entries, or add a new entry below.'=>'Нет записей в глоссарии, соответствующих текущему фильтру. Очистите фильтр, чтобы увидеть все записи, или добавьте новую ниже.','No glossary entries yet. Add one below to start enforcing terminology in translations.'=>'В глоссарии еще нет записей. Добавьте одну ниже, чтобы начать применять терминологию в переводах.','No internal links found to update.'=>'Не найдено внутренних ссылок для обновления.','No language-specific template parts found to map.'=>'Не найдено языко-специфичных частей шаблона для отображения.','No navigation references needed updating.'=>'Нет необходимости обновлять навигационные ссылки.','No override files uploaded yet.'=>'Пока что файлы переопределения не загружены.','No response from provider — check the error log for details.'=>'Нет ответа от провайдера — проверьте журнал ошибок для деталей.','No secondary languages configured. Install a language pack above to enable template scaffolding.'=>'Конфигурация вторичных языков не выполнена. Установите языковой пакет выше, чтобы включить шаблонную структуру.','No source content found to translate.'=>'Не найдено исходного контента для перевода.','No source page linked yet.'=>'Пока что не связана исходная страница.','No template part references needed updating.'=>'Нет необходимости обновлять ссылки на части шаблона.','No {lang} translation registered (TRID missing)'=>'Перевод на {lang} не зарегистрирован (TRID отсутствует)','Notes'=>'Заметки','Notice message'=>'Сообщение уведомления','Notice settings'=>'Настройки уведомлений','Oldest cached block'=>'Самый старый кешированный блок','Oldest cached response'=>'Самый старый кешированный ответ','Only .mo files are accepted.'=>'Допускаются только файлы .mo.','OpenAI (GPT)'=>'OpenAI (GPT)','Optional context for editors (e.g. "ASIC = Application-Specific Integrated Circuit; preserve in English in technical contexts").'=>'Дополнительный контекст для редакторов (например, «ASIC = специализированная интегральная схема; сохранять на английском в технических контекстах»).','Output'=>'Вывод','Output tokens'=>'Выходные токены','overridden'=>'переопределён','Override file deleted.'=>'Файл переопределения удален.','Override file uploaded successfully.'=>'Файл переопределения успешно загружен.','Overrides the AI preset for Translation and Content Generation on this page. All other features always use the global preset.'=>'Переопределяет настройки ИИ для перевода и генерации контента на этой странице. Все остальные функции всегда используют глобальные настройки.','Overrides the AI preset for Translation and Content Generation on this page. Site-wide custom prompt instructions (Settings → Behavior) are always appended to every request regardless of this selection.'=>'Переопределяет настройки ИИ для перевода и генерации контента на этой странице. Общие инструкции для сайта (Настройки → Поведение) всегда добавляются к каждому запросу независимо от этого выбора.','Overview'=>'Обзор','Page'=>'Страница','Part'=>'Часть','Paste a footnote, sentence, or any snippet here…'=>'Вставьте сноску, предложение или любой фрагмент сюда…','Paste text, or select text in the editor first…'=>'Вставьте текст или сначала выберите текст в редакторе…','Paste text, or select text on the page first…'=>'Вставьте текст или сначала выберите текст на странице…','Paste your API key…'=>'Вставьте ваш ключ API…','Path prefix — example.com/de/'=>'Префикс пути — example.com/de/','Pattern'=>'Шаблон','Pattern has no content to translate.'=>'У шаблона нет содержимого для перевода.','Pattern not found.'=>'Шаблон не найден.','Pattern translated and saved. Copy the content into your CPT post via the block editor Pattern inserter or use it as a starting point for a Reusable Block.'=>'Шаблон переведен и сохранен. Скопируйте содержимое в ваш пост CPT через вставщик шаблонов редактора блоков или используйте его как отправную точку для повторно используемого блока.','Pattern translation failed.'=>'Не удалось перевести шаблон.','Per-post cache for AI-generated translations, meta descriptions, excerpts, and content. Always active — no separate toggle required. Entries are invalidated automatically when the content or AI provider/model changes. Use the toolbar "↺ Re-translate" button or click Clear below to force a fresh API call.'=>'Кеш для каждого поста для переводов, метаописаний, выдержек и контента, созданных AI. Всегда активен — не требуется отдельный переключатель. Записи автоматически аннулируются при изменении контента или провайдера/модели AI. Используйте кнопку "↺ Перевести заново" на панели инструментов или нажмите Очистить ниже для принудительного нового вызова API.','Permalink rules flushed successfully.'=>'Правила постоянных ссылок успешно очищены.','Permission denied.'=>'Доступ запрещен.','Persuasive'=>'Убедительный','PHP constant'=>'константа PHP','Pin terms that must not be translated or must always be rendered in a specific way (e.g. brand names, product names, acronyms). Glossary constraints are injected into every AI translation request for all features: post translation, meta description, excerpt, and FSE template translation.'=>'Закрепляйте термины, которые не должны переводиться или должны всегда отображаться определенным образом (например, названия брендов, продуктов, аббревиатуры). Ограничения глоссария внедряются в каждый запрос перевода AI для всех функций: перевод поста, метаописание, выдержка и перевод шаблонов FSE.','Plain language'=>'Простой язык','Please enter some instructions first…'=>'Пожалуйста, сначала введите инструкции…','Please enter some text first…'=>'Пожалуйста, сначала введите текст…','Post'=>'Пост','Post not found.'=>'Пост не найден.','Post Types'=>'Типы записей','Prefilled from excerpt. Edit to override.'=>'Заполнено из аннотации. Измените для переопределения.','Primary Language'=>'Основной язык','Primary language'=>'Основной язык','Primary language saved.'=>'Основной язык сохранен.','Primary language: the language your existing content is written in. All translations are produced from this language; changing it does not move or delete any posts.'=>'Основной язык: язык, на котором написано ваше существующее содержимое. Все переводы создаются с этого языка; его изменение не перемещает и не удаляет посты.','Processing…'=>'Обработка…','Provider'=>'Провайдер','Provider returned no text. Check the WordPress error log for the detailed failure reason.'=>'Поставщик не вернул текст. Проверьте журнал ошибок WordPress для получения подробной причины сбоя.','Quality'=>'Качество','Quality (default — Sonnet / GPT-4o / Gemini Pro)'=>'Качество (по умолчанию — Sonnet / GPT-4o / Gemini Pro)','Quality (Sonnet / GPT-4o / Gemini Pro)'=>'Качество (Sonnet / GPT-4o / Gemini Pro)','Quality: used for post translation and content generation — higher quality, higher cost.'=>'Качество: используется для перевода постов и генерации контента — более высокое качество, более высокая стоимость.','Quick Translate'=>'Быстрый перевод','Quick Translation'=>'Быстрый перевод','Quick Translation is used for snippet/chunk mode — short passages translated on demand from the toolbar, editor, or block popovers. It uses a separate, lighter configuration from the full-page translation to keep responses fast and cost-effective.'=>'Быстрый перевод используется в режиме фрагментов/кусочков — короткие отрывки переводятся по требованию с панели инструментов, редактора или всплывающих окон блока. Он использует отдельную, более легкую конфигурацию по сравнению с переводом всей страницы, чтобы ответы были быстрыми и экономичными.','Re-enables Gutenberg\'s canLockBlocks. Useful for editorial templates that need to prevent contributors from moving or deleting specific blocks.'=>'Восстанавливает canLockBlocks Gutenberg. Полезно для редакционных шаблонов, которым нужно предотвратить перемещение или удаление определённых блоков.','Re-enables supportsTemplateMode. Core to Full-Site-Editing workflows where post-level template overrides are intentional.'=>'Восстанавливает supportsTemplateMode. Основной для рабочих процессов полного редактирования сайта, где преднамеренно переопределяются шаблоны на уровне поста.','Re-generates and updates the cached result.'=>'Обновляет и обновляет кэшированный результат.','Re-scan'=>'Повторное сканирование','Re-scanning…'=>'Повторное сканирование…','Re-translate'=>'Повторный перевод','Redirect visitors to their preferred language based on the browser\'s Accept-Language header'=>'Перенаправлять посетителей на их предпочтительный язык на основе заголовка Accept-Language браузера','Refine further — e.g. "make it shorter" or "use a formal tone"…'=>'Дальнейшая доработка — например, «сделать короче» или «использовать официальный тон»…','Refine further:'=>'Дополнительная доработка:','Refinement'=>'Обработка','Refinement failed — please try again.'=>'Не удалось выполнить обработку — попробуйте еще раз.','Refining…'=>'Обработка…','Regenerates WordPress rewrite rules so URL prefixes, language-specific slugs, and archive rewrites are all in sync. Necessary after changing the primary language or adding new language support.'=>'Восстанавливает правила переписывания WordPress, чтобы префиксы URL, языковые слаги и архивные переписывания были синхронизированы. Необходимо после изменения основного языка или добавления поддержки новых языков.','Remove stored key'=>'Удалить сохранённый ключ','Report an issue on GitHub'=>'Сообщить о проблеме на GitHub','Request failed — please try again.'=>'Запрос не выполнен — попробуйте еще раз.','Request failed.'=>'Запрос не выполнен.','Request failed. Check your connection.'=>'Запрос не выполнен. Проверьте соединение.','Request failed. Please try again.'=>'Запрос не выполнен. Пожалуйста, попробуйте снова.','Requests'=>'Запросы','Reset'=>'Сбросить','Result will appear here…'=>'Результат появится здесь…','Retranslate'=>'Повторный перевод','Retranslating…'=>'Повторный перевод…','Review carefully — links and slugs not updated.'=>'Тщательно проверьте — ссылки и слаги не обновлены.','Review translation before applying'=>'Просмотрите перевод перед применением','Revise'=>'Пересмотреть','Revision'=>'Редакция','Revision Type'=>'Тип редакции','Router'=>'Маршрутизатор','Router Tab'=>'Вкладка Маршрутизатор','Save Debug Setting'=>'Сохранить настройки отладки','Save Router Settings'=>'Сохранить настройки маршрутизатора','Save Settings'=>'Сохранить настройки','Save the post to persist changes.'=>'Сохраните пост, чтобы сохранить изменения.','Save Uninstall Setting'=>'Сохранить настройку удаления','Saved to the meta description field when you apply.'=>'Сохраняется в поле мета-описания при применении.','Scan failed: '=>'Ошибка сканирования: ','Scan request failed. Please try again.'=>'Запрос на сканирование не удался. Пожалуйста, попробуйте снова.','Scanning posts for broken language links…'=>'Сканирование постов на наличие сломанных языковых ссылок…','Search'=>'Поиск','Search Results'=>'Результаты поиска','Security check failed — file path is not permitted.'=>'Ошибка проверки безопасности — путь к файлу не разрешен.','Select a language to manage its FSE templates, template parts, and navigation menus.'=>'Выберите язык для управления его шаблонами FSE, частями шаблонов и меню навигации.','Select language'=>'Выберите язык','SEO character-count info'=>'Информация о количестве символов для SEO','Server setup (subdomain)'=>'Настройка сервера (поддомен)','Sets the default AI behaviour for all features site-wide. Individual posts can override this for Translation and Content Generation via the Lingua Forge meta box.'=>'Устанавливает поведение ИИ по умолчанию для всех функций на сайте. Отдельные посты могут переопределять это для перевода и генерации контента через метабокс Lingua Forge.','Settings'=>'Настройки','Settings saved.'=>'Настройки сохранены.','Show home link'=>'Показать ссылку на главную','Shown when no translation exists for the visitor\'s language.'=>'Показано, когда для языка посетителя не существует перевода.','Single'=>'Одиночная','Single %s'=>'Единичный %s','Single: %s'=>'Единичный: %s','Site-wide ceiling on AI requests per UTC day (counts both Toolbar translations and block revisions). Counter resets at UTC midnight. Set to 0 to disable the cap.'=>'Общий лимит запросов к ИИ на сайте за сутки по UTC (учитывает как переводы в панели инструментов, так и ревизии блоков). Счетчик сбрасывается в полночь по UTC. Установите 0 для отключения ограничения.','Size'=>'Размер','Some link fixes failed.'=>'Некоторые исправления ссылок не удались.','Some nav ref fixes failed.'=>'Некоторые исправления навигационных ссылок не удались.','Some part fixes failed.'=>'Некоторые исправления частей не удались.','Some parts could not be created.'=>'Некоторые части не удалось создать.','Some templates could not be created.'=>'Некоторые шаблоны не удалось создать.','Some translations failed.'=>'Некоторые переводы не удались.','Source file not found.'=>'Исходный файл не найден.','Source lang'=>'Исходный язык','Source language'=>'Исходный язык','Source term'=>'Исходный термин','Standard'=>'Стандартный','Standard uses each feature\'s own tuned temperature: Translation T=0.2 (precise), Quick Translate T=0.4, Content Generator T=0.6 (creative). The other presets apply a single fixed temperature across all features.'=>'Стандарт использует собственную настроенную температуру каждой функции: перевод T=0.2 (точный), быстрый перевод T=0.4, генерация контента T=0.6 (креативный). Другие предустановки применяют одну фиксированную температуру ко всем функциям.','Status'=>'Статус','Status / Actions'=>'Статус / Действия','Storytelling'=>'Рассказывание историй','Strict-preservation mode for legal, regulatory, medical, or technical content. When on, every AI feature uses a low sampling temperature and appends the addendum below to its system prompt — terminology, article numbers, units, brand names, and regulatory language are preserved verbatim rather than paraphrased.'=>'Режим строгого сохранения для юридического, нормативного, медицинского или технического контента. Включённый режим использует низкую температуру выборки для всех функций ИИ и добавляет нижеуказанный дополнение к системной подсказке — терминология, номера статей, единицы измерения, торговые марки и нормативный язык сохраняются дословно, а не перефразируются.','Structured Outline'=>'Структурированный план','Subdomain mode requires your web server to point all language subdomains (e.g. de.example.com) to this WordPress installation. After switching modes, flush permalink rules and clear any caches. If your home URL includes www (e.g. www.example.com), use the lf_base_domain filter to set the bare apex domain so subdomains are constructed correctly.'=>'Режим поддомена требует, чтобы ваш веб-сервер указывал все языковые поддомены (например, de.example.com) на эту установку WordPress. После переключения режимов обновите правила постоянных ссылок и очистите кеши. Если ваш домашний URL включает www (например, www.example.com), используйте фильтр lf_base_domain для установки базового домена, чтобы поддомены создавались правильно.','Subdomain — de.example.com/'=>'Поддомен — de.example.com/','Supported providers: Anthropic (Claude), OpenAI (GPT), Google (Gemini). Only one provider is active at a time. Select the active provider on the General tab.'=>'Поддерживаемые провайдеры: Anthropic (Claude), OpenAI (GPT), Google (Gemini). Активен только один провайдер. Выберите активного провайдера на вкладке Общие.','T=%s'=>'T=%s','T=0.2–0.6, per feature'=>'T=0.2–0.6, для каждой функции','Target lang'=>'Целевой язык','Target Language'=>'Целевой язык','Target language'=>'Целевой язык','Target term'=>'Целевой термин','Target: 140–160 chars for optimal SERP display'=>'Цель: 140–160 символов для оптимального отображения в SERP','Technical'=>'Технический','Technical / Scientific'=>'Технический / Научный','Technical / Scientific instructions'=>'Технические / научные инструкции','Template "%s" already exists.'=>'Шаблон "%s" уже существует.','Template "{expected}" does not exist — create it in the Site Editor first.'=>'Шаблон "{expected}" не существует — сначала создайте его в редакторе сайта.','Template has no content.'=>'У шаблона нет содержимого.','Template mode'=>'Режим шаблона','Template not found or not stored in the database.'=>'Шаблон не найден или не сохранен в базе данных.','Template part "%s" already exists.'=>'Часть шаблона "%s" уже существует.','Template part has no content.'=>'У части шаблона нет содержимого.','Template part not found or not stored in the database.'=>'Часть шаблона не найдена или не сохранена в базе данных.','Template Parts'=>'Части шаблонов','Templates'=>'Шаблоны','Test connection'=>'Проверить соединение','Testing…'=>'Идет тестирование…','Text domain / locale'=>'Текстовая область / локаль','Text to translate'=>'Текст для перевода','The API Response Cache stores the raw result of every AI request — translation, meta description, excerpt, and content generation — keyed by a hash of the inputs (content, language pair, provider, model). Subsequent requests with identical inputs are served from the cache with no API call. The cache is different from Translation Memory: Translation Memory operates at the block level and is shared across posts; the API Response Cache operates at the feature level and is keyed per post.'=>'Кэш ответов API сохраняет необработанный результат каждого запроса AI — перевод, метаописание, выдержка и генерация контента — по хэшу входных данных (содержимое, пара языков, провайдер, модель). Последующие запросы с идентичными входными данными обслуживаются из кэша без вызова API. Кэш отличается от Памяти переводов: Память переводов работает на уровне блока и разделяется между постами; Кэш ответов API работает на уровне функции и привязан к каждому посту.','The editor did not accept the content — please try again.'=>'Редактор не принял содержимое — попробуйте еще раз.','The Light tier uses the fast model configured in the Models table above (default: Haiku / Flash). Switch to Quality if you need the same translation accuracy as full-page mode for snippets.'=>'Уровень Light использует быструю модель, настроенную в таблице моделей выше (по умолчанию: Haiku / Flash). Переключитесь на качество, если вам нужна такая же точность перевода, как в режиме полной страницы для фрагментов.','The phrase as it appears in the source text.'=>'Фраза, как она указана в исходном тексте.','The primary language is always served at the root of your site — no URL prefix in path mode, no language subdomain in subdomain mode. All other languages use either a /lang/ path prefix (e.g. example.com/de/) or a language subdomain (e.g. de.example.com), depending on the URL structure setting below.'=>'Основной язык всегда обслуживается в корне вашего сайта — без префикса URL в режиме пути, без субдомена языка в режиме субдомена. Все остальные языки используют либо префикс пути /lang/ (например, example.com/de/), либо субдомен языка (например, de.example.com), в зависимости от настройки структуры URL ниже.','The source page has no footnotes.'=>'На исходной странице нет сносок.','The upload failed — please try again.'=>'Загрузка не удалась — попробуйте еще раз.','These footnotes come from the source page and are shown here for reference only. Add them to this page using the block editor.'=>'Эти сноски взяты с исходной страницы и показаны здесь только для справки. Добавьте их на эту страницу с помощью редактора блоков.','This is the source page. Footnotes are edited directly in the block editor.'=>'Это исходная страница. Сноски редактируются прямо в редакторе блоков.','This key is currently supplied by a server %s and cannot be removed here. Enter a new key above to override it with a database value.'=>'Этот ключ в настоящее время предоставляется сервером %s и не может быть удалён здесь. Введите новый ключ выше, чтобы переопределить его значением из базы данных.','Tip: to reset a model to the built-in default, clear the field and save.'=>'Совет: чтобы сбросить модель к встроенному значению по умолчанию, очистите поле и сохраните.','To use a custom encryption secret (instead of the derived wp_salt value), add this to wp-config.php:'=>'Чтобы использовать пользовательский секрет шифрования (вместо полученного значения wp_salt), добавьте это в wp-config.php:','Today'=>'Сегодня','Token consumption rolled up by feature, provider, and model. Recorded on every successful AI call; Test Connection pings are deliberately excluded so they don\'t skew the totals. The underlying table aggregates daily — pick a window below to view it.'=>'Потребление токенов по функциям, провайдерам и моделям. Записывается при каждом успешном вызове ИИ; тестовые пинги (Test Connection) специально исключены, чтобы не искажать итоги. Таблица агрегирует данные по дням — выберите окно ниже для просмотра.','Tone'=>'Тон','tone'=>'тон','Tone:'=>'Тон:','Too many AI requests. Please retry in %d seconds.'=>'Слишком много запросов к ИИ. Пожалуйста, повторите через %d секунд.','Total'=>'Итого','Total tokens'=>'Общее количество токенов','Translate'=>'Перевести','Translate / Revise'=>'Перевести / Пересмотреть','Translate / Revise block'=>'Перевести / Пересмотреть блок','Translate all'=>'Перевести всё','Translate chunk'=>'Перевести фрагмент','Translate Content'=>'Перевести контент','Translate missing'=>'Перевод отсутствует','Translate page…'=>'Перевод страницы…','Translated content'=>'Переведённое содержание','Translated Names'=>'Переведённые имена','Translated title'=>'Переведённый заголовок','Translated to:'=>'Переведено на:','Translated. Review in the Site Editor — internal links, navigation URLs, and template slugs are not updated automatically.'=>'Переведено. Проверьте в редакторе сайта — внутренние ссылки, URL-адреса навигации и слаги шаблонов не обновляются автоматически.','Translating…'=>'Перевод…','Translation'=>'Перевод','Translation Caching'=>'Кэширование переводов','Translation found but permalink could not be generated'=>'Обнаружен перевод, но постоянная ссылка не может быть сгенерирована','Translation Limits'=>'Ограничения перевода','Translation Limits & Behavior'=>'Ограничения и поведение при переводе','Translation Limits: control which user roles can trigger AI translation, and set a monthly token budget. Exceeding the budget suspends AI calls until the month resets.'=>'Ограничения на перевод: управлять ролями пользователей, которые могут запускать перевод AI, и установить месячный бюджет токенов. Превышение бюджета приостанавливает вызовы AI до следующего месяца.','Translation Memory'=>'Память переводов','Translation Memory caches AI results by content hash, language pair, provider, and model. Editing a post invalidates the cache entry so the next translate call gets a fresh result.'=>'Кэш памяти переводов сохраняет результаты AI по хэшу содержимого, паре языков, поставщику и модели. Редактирование поста аннулирует запись кэша, чтобы следующий вызов перевода получил свежий результат.','Translation Memory cleared. %d cached block was removed.'=>'Кеш памяти перевода очищен. Удален %d закешированный блок.' . "\0" . 'Кеш памяти перевода очищен. Удалено %d закешированных блоков.' . "\0" . '','Translation Memory: stores the full translated post per content hash. Clear it when you want to force a retranslation of all posts regardless of whether their content changed.'=>'Кэш памяти переводов: хранит полностью переведённый пост по хэшу содержимого. Очистите его, если хотите принудительно перевести все посты заново, независимо от изменений в содержимом.','Translation workflow'=>'Рабочий процесс перевода','Translation, Content Generator'=>'Перевод, генератор контента','Type'=>'Тип','Uli Hake'=>'Ули Хаке','Uninstall Behaviour'=>'Удаление поведения','Uninstall setting saved.'=>'Настройка удаления сохранена.','unknown error'=>'неизвестная ошибка','Unknown provider.'=>'Неизвестный поставщик.','Up'=>'Вверх','Upload .mo file'=>'Загрузить файл .mo','Upload compiled .mo files to override third-party plugin strings for specific locales — for example, a custom VikBooking translation that uses "apartment" instead of "room". Files must follow the WordPress naming convention: {textdomain}-{locale}.mo (e.g. vikbooking-ca.mo). They are stored in the uploads folder and survive plugin updates.'=>'Загружайте скомпилированные файлы .mo, чтобы переопределить строки сторонних плагинов для конкретных локалей — например, пользовательский перевод VikBooking, использующий "apartment" вместо "room". Файлы должны соответствовать соглашению о наименовании WordPress: {textdomain}-{locale}.mo (например, vikbooking-ca.mo). Они хранятся в папке uploads и сохраняются при обновлении плагина.','Upload Override'=>'Загрузить переопределение','URL could not be mapped to a post — check the link target exists'=>'URL не удалось сопоставить с постом — проверьте, существует ли целевой объект','URL structure'=>'Структура URL','URL structure: path-prefix mode (example.com/de/) requires no server changes. Subdomain mode (de.example.com) requires a wildcard DNS record, a wildcard SSL certificate, and a web server configuration change — see the Server Setup guide.'=>'Структура URL: режим с префиксом пути (example.com/de/) не требует изменений на сервере. Режим с поддоменом (de.example.com) требует записи DNS с подстановочным знаком, сертификата SSL с подстановочным знаком и изменения конфигурации веб-сервера — см. руководство по настройке сервера.','Use the tabs across the top of this page to configure each area. Changes to the Router tab take effect immediately; changes to AI keys and model settings apply to the next AI request.'=>'Используйте вкладки в верхней части этой страницы для настройки каждого раздела. Изменения во вкладке маршрутизатора вступают в силу немедленно; изменения ключей AI и настроек модели применяются к следующему запросу AI.','User-managed terminology table per language pair. Entries are appended to the translation system prompt so the AI uses preferred terms consistently — critical for domain vocabulary ("kWp", "PPA", "interconnection point"), brand names that must not translate, and standardised regulatory phrasing. Both language fields are optional: leave "Source language" blank to apply the entry regardless of which language you are translating from; leave "Target language" blank to apply it to all target languages at once.'=>'Таблица терминов, управляемая пользователем, для каждой языковой пары. Записи добавляются в подсказку системы перевода, чтобы ИИ использовал предпочтительные термины последовательно — критично для терминологии области («кВт», «PPA», «точка подключения»), названий брендов, которые не должны переводиться, и стандартизированной нормативной формулировки. Обе языковые поля являются необязательными: оставьте «Исходный язык» пустым, чтобы применить запись независимо от языка исходного текста; оставьте «Целевой язык» пустым, чтобы применить её ко всем целевым языкам сразу.','Using custom meta description.'=>'Использование пользовательского мета-описания.','View'=>'Просмотр','View built-in default'=>'Просмотр встроенного значения по умолчанию','View details'=>'Просмотреть детали','View Lingua Forge details'=>'Просмотреть детали Lingua Forge','Visit plugin site'=>'Посетить сайт плагина','Warning:'=>'Внимание:','When debug logging is enabled (via the toggle below or by defining LINGUAFORGE_AI_DEBUG in wp-config.php), the Translation and FSE template translation features write their raw AI prompts and responses to disk for troubleshooting. Use this section to monitor that output and clear it once you have what you need — the files can grow quickly on large pages. Configure the destination directory via the linguaforge_debug_dir filter.'=>'Когда включено ведение журнала отладки (через переключатель ниже или определяя LINGUAFORGE_AI_DEBUG в wp-config.php), функции перевода и шаблонов FSE записывают свои необработанные подсказки AI и ответы на диск для устранения неполадок. Используйте этот раздел для мониторинга этого вывода и очистки его после получения нужных данных — файлы могут быстро расти на больших страницах. Настройте каталог назначения через фильтр linguaforge_debug_dir.','When enabled, first-time visitors with no language cookie and no language prefix in the URL are redirected to the closest matching language version. The redirect is skipped if the browser\'s preferred language is not among the active router languages. Once a visitor selects a language via the switcher, the cookie takes priority and the browser header is ignored on all future visits.'=>'При включении, посетители в первый раз без cookie языка и без префикса языка в URL перенаправляются на наиболее подходящую версию языка. Перенаправление пропускается, если предпочтительный язык браузера не входит в активные языки маршрутизатора. После выбора языка через переключатель, приоритет имеет cookie, и заголовок браузера игнорируется при всех последующих посещениях.','Which model tier to use for full-page translation. Quality uses the model configured in the Models table above and is recommended for accurate, long-form translation. Switch to Light only if speed or cost is the priority and the content is short.'=>'Какой уровень модели использовать для перевода всей страницы. Качество использует модель, настроенную в таблице моделей выше, и рекомендуется для точного, длинного перевода. Переключайтесь на Легкий только если важна скорость или стоимость, а содержание короткое.','WP-CLI reference'=>'Справка WP-CLI','Write AI prompts and responses to disk for troubleshooting'=>'Записывать подсказки AI и ответы на диск для устранения неполадок','You can also define keys as constants or environment variables (e.g. in wp-config.php). Those sources are used automatically as a fallback when no database key is stored.'=>'Вы также можете определить ключи как константы или переменные окружения (например, в wp-config.php). Эти источники используются автоматически в качестве резервного варианта, когда ключ из базы данных не сохранён.','You do not have permission to manage these settings.'=>'У вас нет разрешения управлять этими настройками.','You do not have permission to read this post.'=>'У вас нет разрешения на чтение этого поста.','{n} stale path(s)'=>'{n} устаревший(ие) путь(и)','— Any source language —'=>'— Любой исходный язык —','— Any target language —'=>'— Любой целевой язык —','— Any target —'=>'— Любой целевой —','— Any —'=>'— Любой —','— auto-detect —'=>'— автоопределение —','— select a language —'=>'— выберите язык —','— toggle in Settings → Behavior.'=>'— переключатель в Настройках → Поведение.','← Back'=>'← Назад','↑ Detected from current post'=>'↑ Обнаружено из текущего поста','↺ Re-translate'=>'↺ Повторный перевод','↺ Refine'=>'↺ Доработка','↺ Refresh'=>'↺ Обновить','↺ Refreshing…'=>'↺ Обновление…','⚠ Borderline'=>'⚠ Граничное значение','⚠ No <strong>{lang}</strong> posts found. Make sure all translated posts have their Language meta set to <strong>{lang}</strong> in the Language metabox.'=>'⚠ Не найдены посты <strong>{lang}</strong>. Убедитесь, что все переведённые посты имеют мета-параметр Язык, установленный в <strong>{lang}</strong> в метаблоке языка.','⚠ No changes'=>'⚠ Нет изменений','⚠ No changes — re-scan?'=>'⚠ Нет изменений — повторное сканирование?','✅ Fixed ({n})'=>'✅ Исправлено ({n})','✅ No broken links or template mismatches found for <strong>{lang}</strong>. Scanned <strong>{scanned}</strong> post(s) and page(s) — all checks passed. Template part links (header, footer, sidebar) are not included here — use the Fix Template Parts button to check those separately.'=>'✅ Не обнаружено сломанных ссылок или несоответствий шаблонов для <strong>{lang}</strong>. Проведено сканирование <strong>{scanned}</strong> постов и страниц — все проверки прошли успешно. Ссылки на части шаблонов (шапка, подвал, боковая панель) здесь не включены — используйте кнопку Исправить части шаблонов для их отдельной проверки.','✅ Template fixed'=>'✅ Шаблон исправлен','✓ All parts created.'=>'✓ Все части созданы.','✓ All templates created.'=>'✓ Все шаблоны созданы.','✓ All translated.'=>'✓ Все переведено.','✓ Configured'=>'✓ Настроено','✓ Connection OK'=>'✓ Соединение в порядке','✓ Content generated — see the overlay to review, refine, and apply.'=>'✓ Контент сгенерирован — посмотрите оверлей для просмотра, доработки и применения.','✓ Done'=>'✓ Готово','✓ Enabled'=>'✓ Включено','✓ Good length'=>'✓ Хорошая длина','✓ In safe storage'=>'✓ В безопасном хранилище','✓ Language installed.'=>'✓ Язык установлен.','✓ Links fixed.'=>'✓ Ссылки исправлены.','✓ Nav refs fixed.'=>'✓ Исправлены навигационные ссылки.','✓ Parts fixed.'=>'✓ Части исправлены.','✓ Pattern translated.'=>'✓ Шаблон переведен.','✓ Refined — review the updated draft above.'=>'✓ Обработано — просмотрите обновленный черновик выше.','✓ Translation saved'=>'✓ Перевод сохранён','✗ Disabled'=>'✗ Отключено','✗ Error:'=>'✗ Ошибка:','✗ Failed:'=>'✗ Не удалось: ','✗ Not configured'=>'✗ Не настроено','✗ Too long'=>'✗ Слишком длинно','✗ Too short'=>'✗ Слишком коротко','❌ Failed'=>'❌ Не удалось','📄 Wrong template'=>'📄 Неправильный шаблон','📍 Stale path (page moved)'=>'📍 Устаревший путь (страница перемещена)']];
